/* shared-sql.js - in-browser SQL trainer for block 11 (SQLite via sql.js / WebAssembly).
 *
 * Markup on a lesson page:
 *   <div class="sql-schema"></div>                 tables, columns and a 5-row preview
 *   <div class="sql-example" data-sql="SELECT …">  runnable example from the theory text
 *   <div class="sql-sandbox"></div>                free query editor
 *   <div class="sql-lab" data-sql-part="1"></div>  tasks of one part
 * Data: 11_sql/sql-course-data.js (window.__mlSqlCourse), generated by scripts/sql-course/build.mjs.
 * An answer is correct when its result has the same number of columns and the same rows
 * (numbers compared to 2 decimals) as the reference solution; row order matters only when the
 * task says so. Column names are not checked. Progress: localStorage "ml_notes_sql".
 */
(function () {
  var data = window.__mlSqlCourse;
  if (!data) return;
  var STORE = "ml_notes_sql";
  var MAX_ROWS = 50;
  var dbPromise = null;

  function readStore() { try { return JSON.parse(localStorage.getItem(STORE)) || {}; } catch (e) { return {}; } }
  function writeStore(s) { try { localStorage.setItem(STORE, JSON.stringify(s)); } catch (e) { /* storage disabled */ } }
  var store = readStore();

  function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
  function el(tag, cls, html) { var e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }

  // ---------- database ----------
  function loadScript(src) {
    return new Promise(function (resolve, reject) {
      var s = document.createElement("script");
      s.src = src; s.onload = resolve; s.onerror = function () { reject(new Error("не удалось загрузить " + src)); };
      document.head.appendChild(s);
    });
  }
  function freshDb(SQL) {
    var db = new SQL.Database();
    db.run(data.schemaSql);
    db.run(data.seedSql);
    return db;
  }
  function getDb() {
    if (dbPromise) return dbPromise;
    var base = "../vendor/sqljs/";
    dbPromise = loadScript(base + "sql-wasm.js").then(function () {
      if (location.protocol === "file:") {
        // browsers block fetching .wasm from file:// pages: use the embedded copy
        return loadScript(base + "sql-wasm-base64.js").then(function () {
          var bin = atob(window.__sqlWasmBase64), bytes = new Uint8Array(bin.length);
          for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
          return window.initSqlJs({ wasmBinary: bytes });
        });
      }
      return window.initSqlJs({ locateFile: function (f) { return base + f; } });
    }).then(function (SQL) { return { SQL: SQL, db: freshDb(SQL) }; });
    return dbPromise;
  }
  var WRITE_RE = /\b(insert|update|delete|drop|create|alter|replace|attach|pragma)\b/i;
  function run(sql) {
    return getDb().then(function (h) {
      var res;
      try { res = h.db.exec(sql); }
      finally { if (WRITE_RE.test(sql)) { h.db.close(); h.db = freshDb(h.SQL); } } // keep the dataset intact
      if (!res.length) return { columns: [], values: [] };
      return res[res.length - 1];
    });
  }

  // ---------- result rendering / checking ----------
  function renderTable(res, box) {
    box.innerHTML = "";
    if (!res.columns.length) { box.appendChild(el("p", "sql-msg", "Запрос выполнен, но не вернул строк-результата.")); return; }
    var wrap = el("div", "sql-table-wrap"), table = el("table", "sql-table");
    var thead = el("thead"), tr = el("tr");
    res.columns.forEach(function (c) { tr.appendChild(el("th", null, esc(c))); });
    thead.appendChild(tr); table.appendChild(thead);
    var tbody = el("tbody");
    res.values.slice(0, MAX_ROWS).forEach(function (row) {
      var r = el("tr");
      row.forEach(function (v) { r.appendChild(el("td", v === null ? "sql-null" : null, v === null ? "NULL" : esc(v))); });
      tbody.appendChild(r);
    });
    table.appendChild(tbody); wrap.appendChild(table); box.appendChild(wrap);
    box.appendChild(el("p", "sql-count", res.values.length + (res.values.length === 1 ? " строка" : " строк") +
      (res.values.length > MAX_ROWS ? ", показаны первые " + MAX_ROWS : "")));
  }
  function norm(v) {
    if (v === null || v === undefined) return null;
    if (typeof v === "number") return Math.round(v * 100) / 100;
    if (typeof v === "string" && /^-?\d+(\.\d+)?$/.test(v.trim())) return Math.round(parseFloat(v) * 100) / 100;
    return String(v).trim();
  }
  function rowKey(row) { return JSON.stringify(row.map(norm)); }
  function compare(mine, ref, ordered) {
    if (!mine.columns.length) {
      return { ok: false, msg: "Запрос не вернул ни одной строки, а в ответе их " + ref.values.length + ". Проверьте условия фильтрации и соединения." };
    }
    if (mine.columns.length !== ref.columns.length) {
      return { ok: false, msg: "Столбцов в результате " + mine.columns.length + ", а нужно " + ref.columns.length + ". Проверьте список после SELECT." };
    }
    if (mine.values.length !== ref.values.length) {
      return { ok: false, msg: "Строк в результате " + mine.values.length + ", а нужно " + ref.values.length + ". Проверьте условия фильтрации и соединения." };
    }
    var a = mine.values.map(rowKey), b = ref.values.map(rowKey);
    if (ordered) {
      var sameSet = a.slice().sort().join("\n") === b.slice().sort().join("\n");
      if (a.join("\n") === b.join("\n")) return { ok: true };
      return { ok: false, msg: sameSet ? "Строки верные, но порядок другой — задание требует сортировку." : "Число строк совпадает, но значения отличаются." };
    }
    return a.sort().join("\n") === b.sort().join("\n") ? { ok: true } : { ok: false, msg: "Число строк совпадает, но значения отличаются. Проверьте порядок столбцов, условия и формулы." };
  }

  // ---------- editor ----------
  function makeEditor(initial, onRun, label) {
    var area = el("textarea", "sql-editor");
    area.value = initial || "";
    area.spellcheck = false;
    area.setAttribute("aria-label", label || "SQL-запрос");
    function autosize() { area.style.height = "auto"; area.style.height = Math.min(area.scrollHeight + 2, 360) + "px"; }
    area.addEventListener("input", autosize);
    requestAnimationFrame(autosize);
    area.addEventListener("keydown", function (e) {
      if ((e.ctrlKey || e.metaKey) && e.key === "Enter") { e.preventDefault(); onRun(); }
      if (e.key === "Tab" && !e.shiftKey) { // insert two spaces instead of leaving the editor
        e.preventDefault();
        var s = area.selectionStart; area.value = area.value.slice(0, s) + "  " + area.value.slice(area.selectionEnd); area.selectionStart = area.selectionEnd = s + 2;
      }
    });
    return area;
  }
  function errorBox(box, err) {
    box.innerHTML = "";
    box.appendChild(el("p", "sql-msg sql-msg--error", "Ошибка SQL: " + esc(err && err.message ? err.message : err)));
  }

  // ---------- schema ----------
  function renderSchema(host) {
    host.appendChild(el("p", "sql-schema__lead", "База магазина «Вольт» (SQLite). Нажмите на таблицу, чтобы увидеть первые строки."));
    var grid = el("div", "sql-schema__grid");
    data.tables.forEach(function (t) {
      var card = el("details", "sql-schema__table");
      var sum = el("summary", null, "<code>" + t.name + "</code> <span>" + esc(t.about) + " · " + t.rows + " строк</span>");
      card.appendChild(sum);
      var ul = el("ul", "sql-schema__cols");
      t.columns.forEach(function (c) { ul.appendChild(el("li", null, "<code>" + c[0] + "</code> <span class=\"sql-type\">" + c[1] + "</span> — " + esc(c[2]))); });
      card.appendChild(ul);
      var preview = el("div", "sql-result");
      card.appendChild(preview);
      card.addEventListener("toggle", function () {
        if (card.open && !preview.childNodes.length) {
          preview.textContent = "Загрузка…";
          run("SELECT * FROM " + t.name + " LIMIT 5").then(function (r) { renderTable(r, preview); }, function (e) { errorBox(preview, e); });
        }
      });
      grid.appendChild(card);
    });
    host.appendChild(grid);
  }

  // ---------- example / sandbox ----------
  function renderRunner(host, sql, opts) {
    var box = el("div", "sql-runner");
    var result = el("div", "sql-result");
    function go() {
      result.textContent = "Выполняю…";
      run(area.value).then(function (r) { renderTable(r, result); }, function (e) { errorBox(result, e); });
    }
    var area = makeEditor(sql, go, opts.label);
    var bar = el("div", "sql-actions");
    var btn = el("button", "sql-btn sql-btn--primary", "Запустить <kbd>Ctrl+Enter</kbd>");
    btn.type = "button"; btn.addEventListener("click", go);
    bar.appendChild(btn);
    box.appendChild(area); box.appendChild(bar); box.appendChild(result);
    host.appendChild(box);
  }

  // ---------- tasks ----------
  function renderLab(host, part) {
    var tasks = data.tasks.filter(function (t) { return t.part === part; });
    var allBefore = data.tasks.filter(function (t) { return t.part < part; }).length;
    var nav = el("ol", "sql-nav");
    var progress = el("p", "sql-progress");
    host.appendChild(progress);
    host.appendChild(nav);
    function updateProgress() {
      var done = tasks.filter(function (t) { return store[t.id] && store[t.id].solved; }).length;
      var total = data.tasks.filter(function (t) { return store[t.id] && store[t.id].solved; }).length;
      progress.textContent = "Решено в этой части: " + done + " из " + tasks.length + " · во всём курсе: " + total + " из " + data.tasks.length;
      Array.prototype.forEach.call(nav.children, function (li, i) {
        li.classList.toggle("is-solved", !!(store[tasks[i].id] && store[tasks[i].id].solved));
      });
    }
    tasks.forEach(function (t, i) {
      var n = allBefore + i + 1;
      var li = el("li", null, "<a href=\"#task-" + t.id + "\"><span class=\"sql-nav__mark\" aria-hidden=\"true\"></span>" + esc(t.title) + " <code>" + esc(t.topic) + "</code></a>");
      nav.appendChild(li);

      var card = el("section", "sql-task");
      card.id = "task-" + t.id;
      var head = el("div", "sql-task__head");
      head.appendChild(el("span", "sql-chip", n + " / " + data.tasks.length));
      head.appendChild(el("span", "sql-chip", esc(t.topic)));
      var status = el("span", "sql-chip sql-chip--status");
      head.appendChild(status);
      card.appendChild(head);
      card.appendChild(el("h3", "sql-task__title", esc(t.title)));
      card.appendChild(el("p", "sql-task__story", t.story));
      card.appendChild(el("p", "sql-task__goal", t.task + (t.ordered ? " <em>Порядок строк важен.</em>" : "")));

      var saved = store[t.id] || {};
      var result = el("div", "sql-result");
      var feedback = el("p", "sql-feedback");
      feedback.setAttribute("role", "status");
      var hintBox = el("ol", "sql-hints");
      var explain = el("div", "sql-explain", "<strong>Разбор.</strong> " + t.explain);
      explain.hidden = true;
      var solutionBox = el("pre", "sql-solution");
      solutionBox.hidden = true;
      solutionBox.textContent = t.solution;

      function markSolved() {
        status.textContent = "решено ✓";
        status.classList.add("is-solved");
        explain.hidden = false;
      }
      function check() {
        var q = area.value.trim();
        if (!q) return;
        store[t.id] = Object.assign(store[t.id] || {}, { query: q });
        writeStore(store);
        result.textContent = "Выполняю…";
        feedback.textContent = "";
        feedback.className = "sql-feedback";
        Promise.all([run(q), run(t.solution)]).then(function (rs) {
          renderTable(rs[0], result);
          var c = compare(rs[0], rs[1], t.ordered);
          if (c.ok) {
            feedback.textContent = "Верно! " + (i + 1 < tasks.length ? "Можно переходить к следующему заданию." : "Часть пройдена.");
            feedback.classList.add("is-ok");
            store[t.id].solved = true;
            writeStore(store);
            markSolved();
            updateProgress();
          } else {
            feedback.textContent = "Пока не совпадает. " + c.msg;
            feedback.classList.add("is-wrong");
          }
        }, function (e) { errorBox(result, e); });
      }
      var area = makeEditor(saved.query || "", check, "Запрос для задания «" + t.title + "»");
      area.placeholder = "-- ваш запрос; Ctrl+Enter — запустить";
      var bar = el("div", "sql-actions");
      function btn(label, cls, fn) { var b = el("button", "sql-btn " + (cls || ""), label); b.type = "button"; b.addEventListener("click", fn); bar.appendChild(b); return b; }
      btn("Проверить <kbd>Ctrl+Enter</kbd>", "sql-btn--primary", check);
      var hintBtn = btn("Подсказка (" + t.hints.length + ")", "", function () {
        var shown = hintBox.children.length;
        if (shown < t.hints.length) hintBox.appendChild(el("li", null, t.hints[shown]));
        hintBtn.disabled = hintBox.children.length >= t.hints.length;
      });
      btn("Показать решение", "", function () {
        if (!solutionBox.hidden) return;
        if (!window.confirm("Показать эталонное решение? Сначала попробуйте подсказки.")) return;
        solutionBox.hidden = false; explain.hidden = false;
      });
      btn("Очистить", "", function () { area.value = ""; area.focus(); });

      card.appendChild(area);
      card.appendChild(bar);
      card.appendChild(hintBox);
      card.appendChild(feedback);
      card.appendChild(result);
      card.appendChild(solutionBox);
      card.appendChild(explain);
      if (saved.solved) markSolved();
      host.appendChild(card);
    });
    updateProgress();
    var reset = el("button", "sql-link", "Сбросить прогресс этой части");
    reset.type = "button";
    reset.addEventListener("click", function () {
      if (!window.confirm("Стереть решения и прогресс заданий этой части?")) return;
      tasks.forEach(function (t) { delete store[t.id]; });
      writeStore(store);
      location.reload();
    });
    host.appendChild(reset);
  }

  function init() {
    document.querySelectorAll(".sql-schema").forEach(renderSchema);
    document.querySelectorAll(".sql-example").forEach(function (h) { renderRunner(h, h.getAttribute("data-sql"), { label: "Пример SQL-запроса", rows: 3 }); });
    document.querySelectorAll(".sql-sandbox").forEach(function (h) { renderRunner(h, h.getAttribute("data-sql") || "SELECT * FROM orders LIMIT 10;", { label: "Песочница SQL", rows: 6 }); });
    document.querySelectorAll(".sql-lab").forEach(function (h) { renderLab(h, Number(h.getAttribute("data-sql-part"))); });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init); else init();
})();
